    for (prev_start, prev_end, _), (start, end, _) in zip(ordered, ordered[1:]):
        if start < prev_end:
            raise BacktraceError(
                "invalid_field",
                f"symbol intervals overlap: [{prev_start:#x}, {prev_end:#x}) and [{start:#x}, {end:#x})",
            )
    return symbols


